import{z as B,x as o,o as t,c as p,q as r,j as A,D as e,d as s,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"恰好一次","description":"","frontmatter":{"title":"恰好一次","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exactly-once.md","filePath":"cs/exactly-once.md","lastUpdated":1791413859000}'),d={name:"cs/exactly-once.md"};function c(C,a,D,m,k,F){const n=o("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="恰好一次" tabindex="-1">恰好一次 <a class="header-anchor" href="#恰好一次" aria-label="Permalink to &quot;恰好一次&quot;">​</a></h1><div class="epigraph"><p>端到端恰好一次不是「消息只投一次」，而是效果幂等：重复投递不改变状态。检查点、事务 sink 与去重键一起才够。</p><footer>—— 据流系统 exactly-once 实践（Kafka transactions、Flink 检查点）；网络课重试幂等对照</footer></div><p><a href="/cs/watermark-late-events">上一课</a>让窗口能关。缺口是故障：算子重跑会把同一窗口结果写两遍。本课钉恰好一次；TPC 下一课换成基准，不在这里写协议细节到可利用的程度。与 <a href="/cs/retry-idempotency">重试幂等</a> 对照：那是 RPC，这是流状态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>至少一次：简单，重复。至多一次：丢。恰好一次：需要 (1) 输入可重放；(2) 算子状态与输入偏移一起检查点；(3) sink 事务或幂等键。缺口是<strong>效果</strong>，不是网卡只发一帧。外部副作用（发邮件）没有事务就只能幂等。</p><p><span class="marginnote">「Kafka exactly-once」指事务生产者与读已提交；跨多个异构 sink 仍要自己的幂等设计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检查点：对齐或非对齐 barrier，状态后端快照。sink：两阶段提交或按主键 upsert。去重：事件 ID 在窗口内。失败：从检查点重放，sink 回滚或覆盖。与湖仓：表快照提交是事务 sink。</p>',8)),(t(),A(l,null,{default:e(()=>[i(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%8F%AF%E9%87%8D%E6%94%BE%E8%BE%93%E5%85%A5%22%5D%20--%3E%20CKPT%5B%22%E7%8A%B6%E6%80%81%20%2B%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20CKPT%20--%3E%20SINK%5B%22%E4%BA%8B%E5%8A%A1%20%2F%20%E5%B9%82%E7%AD%89%E5%86%99%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：检查点就是给整条流式作业拍「全家福」的手段——在某一时刻把所有算子的状态和「输入读到哪了」（偏移）一起存下来。崩溃后翻出这张照片原地重开，输入也从照片里的位置重放，才既不多算也不漏算。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"确定性重算 + 原子提交使第二次效果等于第一次。非确定性（随机、系统时间当事件时间）会打破。barrier 对齐等待最慢分区，与 watermark 的 min 同类。检查点间隔即 RPO：未检查点的丢失像异步提交。事务 sink 把偏移与写出同一提交；否则至少一次加下游幂等键（窗口+键+版本）。",-1)),(t(),A(l,null,{default:e(()=>[i(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%AA%97%E5%8F%A3%E7%AE%97%E5%AE%8C%EF%BC%8C%E5%86%99%20sink%22%5D%20--%3E%20F%7B%22%E5%86%99%E5%AE%8C%E5%89%8D%E7%AE%97%E5%AD%90%E5%B4%A9%E6%BA%83%EF%BC%9F%22%7D%0A%20%20F%20--%20%22%E5%90%A6%22%20--%3E%20P%5B%22%E4%BA%8B%E5%8A%A1%20sink%EF%BC%9A%E9%A2%84%E5%86%99%E5%86%8D%E6%8F%90%E4%BA%A4%22%5D%0A%20%20F%20--%20%22%E6%98%AF%22%20--%3E%20R%5B%22%E4%BB%8E%E6%9C%80%E8%BF%91%E6%A3%80%E6%9F%A5%E7%82%B9%E9%87%8D%E6%94%BE%EF%BC%8C%E7%8A%B6%E6%80%81%E4%B8%8E%E5%81%8F%E7%A7%BB%E4%B8%80%E8%B5%B7%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20R%20--%3E%20P2%5B%22%E6%9C%AA%E6%8F%90%E4%BA%A4%E7%9A%84%20sink%20%E4%BA%8B%E5%8A%A1%E4%BD%9C%E5%BA%9F%EF%BC%8C%E4%B8%8D%E7%95%99%E4%B8%8B%E5%8D%8A%E4%B8%AA%E7%BB%93%E6%9E%9C%22%5D%0A%20%20P2%20--%3E%20P%0A%20%20P%20--%3E%20D%7B%22%E4%B8%8B%E6%B8%B8%E6%94%AF%E6%8C%81%E4%BA%8B%E5%8A%A1%EF%BC%9F%22%7D%0A%20%20D%20--%20%22%E5%90%A6%22%20--%3E%20K%5B%22%E9%80%80%E4%B8%80%E6%AD%A5%E7%94%A8%E5%B9%82%E7%AD%89%E9%94%AE%20upsert%EF%BC%8C%E9%87%8D%E5%A4%8D%E5%86%99%E8%A2%AB%E8%A6%86%E7%9B%96%22%5D%0A%20%20D%20--%20%22%E6%98%AF%22%20--%3E%20S%5B%22%E6%8F%90%E4%BA%A4%E5%8E%9F%E5%AD%90%E7%94%9F%E6%95%88%EF%BC%8C%E6%95%88%E6%9E%9C%E6%81%B0%E5%A5%BD%E4%B8%80%E6%AC%A1%22%5D%0A%20%20K%20--%3E%20S%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：检查点每 30 秒打一次，作业在第 29 秒崩溃，最后 29 秒的进度就靠重放追回——若下游按「收到一条就加一」计数，这段时间的事件会被数两遍。间隔越长吞吐越好、但重放越久：这个间隔就是容灾里说的 RPO（能容忍丢多少进度）。</span></p><p>CDC 槽推进类似偏移提交。杀工人重放是测试手段，不是协议漏洞利用。端到端三处对齐：源、状态、sink 缺一则重复或丢。外部副作用（邮件）没有事务就只能幂等。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供绕过幂等去刷写外部系统的办法。下一课基准测吞吐，不测你是否真 exactly-once。Jepsen 再后课测隔离声明。跨多个异构 sink 仍要各自的幂等设计，单靠 Kafka 事务不够。</p><p>后课默认：跨系统用幂等或事务对齐偏移。没有幂等键的「事务 sink」在非事务下游上仍会重复。</p><p><span class="marginnote">常见误区：初学者以为「恰好一次」是消息真的只在网上跑一趟——重试与重复投递根本拦不住；它说的是<strong>效果</strong>恰好一次：同一事件算两遍、写两遍，最终状态里只体现一份。也别以为打开 Kafka 事务就全局恰好一次：发邮件这类外部副作用出了事务边界，仍要自己拿业务键做幂等。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恰好一次是状态效果幂等，不是物理只投一次。</li><li>检查点必须绑输入偏移；sink 要事务或幂等键。</li><li>TPC-C / TPC-H 下一课。</li><li>出处：流引擎检查点与 Kafka 事务公开设计；对照网络幂等课。</li></ul>',8))])}const u=B(d,[["render",c]]);export{h as __pageData,u as default};
